<template><div class="app-container supplychain-operations"><p class="muted">统一查看当前未解决的采购、仓库、入账及加工问题；同单同类问题归集展示。默认查询近90天单据，完整单号可查询更早记录。</p><div class="links"><el-button size="small" @click="$router.push('/oms-supplychain/poInfo')">采购单</el-button><el-button size="small" @click="$router.push('/oms-supplychain/arrivals')">到货单</el-button><el-button size="small" @click="$router.push('/oms-supplychain/wmsTickets')">出入库单</el-button></div><el-form inline size="small" @submit.native.prevent="search"><el-form-item label="单号"><el-input v-model.trim="query.number" clearable placeholder="完整采购 / 到货 / 入库 / 加工单号" @keyup.enter.native="search"/></el-form-item><el-form-item label="接收或执行虚仓"><el-input v-model.trim="query.store" clearable placeholder="完整虚仓编码"/></el-form-item><el-form-item label="单据创建日期"><el-date-picker v-model="dates" type="daterange" value-format="yyyy-MM-dd" start-placeholder="开始日期" end-placeholder="结束日期"/></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><div class="buckets"><button v-for="(label,key) in labels" :key="key" :class="{selected:query.issue===key}" @click="query.issue=key;search()">{{ label }} <b>{{ counts[key]||0 }}</b></button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="rows" v-loading="loading" size="small" empty-text="当前筛选范围内没有未解决待办"><el-table-column label="待办类型 / 单据" min-width="280"><template slot-scope="{row}"><el-tag size="mini" type="warning">{{ labels[row.issue] }}</el-tag><div><el-button type="text" @click="open(row)">{{ row.document_sn }}</el-button></div><div v-if="row.po_sn&&row.po_sn!==row.document_sn" class="muted">采购 {{ row.po_sn }}</div></template></el-table-column><el-table-column label="供应商 / 虚仓" min-width="220"><template slot-scope="{row}">{{ row.supplier_name || '来源业务中查看' }}<div class="muted">{{ row.store_code }}</div></template></el-table-column><el-table-column label="当前原因 / 影响数量" min-width="340"><template slot-scope="{row}">{{ reason(row.reason) }}<div class="muted">{{ row.quantity==null?'数量按原明细核对':'本问题数量 '+row.quantity+'，具体单位见原明细' }}</div></template></el-table-column><el-table-column label="创建 / 预计日期" min-width="170"><template slot-scope="{row}">{{ row.create_time }}<div v-if="row.due_time" class="muted">预计 {{ row.due_time }}</div></template></el-table-column><el-table-column label="操作" width="120"><template slot-scope="{row}"><el-button type="text" @click="open(row)">查看并处理</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" :page-sizes="[20,50]" @pagination="load"/></div></template>
<script>
import { operations } from '@/api/purchase/workspace'
const defaults=()=>({number:'',store:'',issue:'',pageNum:1,pageSize:20})
export default{data:()=>({query:defaults(),dates:[],rows:[],counts:{},total:0,loading:false,error:'',sequence:0,labels:{'':'全部待办',STOCK_DIFFERENCE:'仓库库存待核查',TRANSFER:'调拨在途待处理',PARCEL:'退仓包裹待核对',RESTORE:'退仓恢复待审核',SUPPLIER:'退仓供应商验收待确认',REMAINING:'退仓剩余待处理',RECLAIM:'拒收收回待处理',OVERDUE:'到货逾期',DISPATCH:'下发失败',UNKNOWN:'结果待确认',QUERY:'最近查询异常',RECEIPT:'收货回传待补齐',POSTING:'入账异常',CUTOFF:'截单待确认',REVIEW:'仓库回传待核对',DIFFERENCE:'收货差异',RETURN:'售后退回待核对',PROCESS:'加工待核对'}}),created(){this.load()},beforeDestroy(){this.sequence++},methods:{search(){this.query.pageNum=1;this.load()},reset(){this.query=defaults();this.dates=[];this.load()},reason(text){return String(text||'').replace(/^SHORT：/,'最终短收：').replace(/^QUALITY：/,'次品：').replace(/^OVER：/,'超收：').replace(/^WRONG_SKU：/,'错货：').replace(/^LATE：/,'迟到回传额度冲突：')},async load(){const seq=++this.sequence;this.loading=true;this.error='';try{const d=(await operations({...this.query,from:this.dates&&this.dates[0]||'',to:this.dates&&this.dates[1]||''})).data;if(seq===this.sequence){this.rows=d.rows||[];this.counts=d.counts||{};this.total=Number(d.total)}}catch(_){if(seq===this.sequence){this.rows=[];this.counts={};this.total=0;this.error='供应链待办加载失败，请核对筛选条件或刷新重试'}}finally{if(seq===this.sequence)this.loading=false}},open(row){this.$router.push(row.kind==='transfer'?{path:'/oms-supplychain/warehouseTransfers',query:{id:row.document_id}}:row.kind==='reconciliation'?{path:'/oms-supplychain/warehouseReconciliation',query:{id:row.document_id}}:row.kind==='purchaseReclaim'?{path:'/oms-supplychain/purchaseReturns',query:{reclaimId:row.document_id}}:row.kind==='purchaseReturn'?{path:'/oms-supplychain/purchaseReturns',query:{id:row.document_id}}:row.kind==='process'?{path:'/oms-inventory/kitProcess',query:{id:row.document_id}}:row.kind==='ticket'?{path:'/oms-supplychain/wmsTickets',query:{documentId:row.document_id,sn:row.document_sn}}:row.kind==='purchase'?{path:'/oms-supplychain/poInfo',query:{purchaseId:row.document_id,poSn:row.document_sn}}:{path:'/oms-supplychain/arrivals',query:{receiptId:row.document_id,differenceId:row.difference_id||undefined}})}}}
</script>
<style scoped>.muted{font-size:12px;color:#7a899d;line-height:1.9;overflow-wrap:anywhere}.links{display:flex;gap:12px;margin:18px 0}.links .el-button{margin:0}.el-form{border:1px solid #e3eaf3;border-radius:8px;padding:18px 18px 0;margin:18px 0}.el-form .el-input{width:320px}.buckets{display:flex;gap:9px;flex-wrap:wrap;margin:18px 0}.buckets button{padding:10px 13px;border:1px solid #e3eaf3;border-radius:6px;background:#f5f8fc;color:#536780;cursor:pointer}.buckets button.selected{background:#edf5ff;border-color:#87b8ef;color:#0877dc}.buckets b{margin-left:8px}.supplychain-operations ::v-deep .cell{overflow-wrap:anywhere}.supplychain-operations ::v-deep .el-button--text{white-space:normal;text-align:left}</style>
